 "content": "def transform(grid):
    """Fill the interiors of monochrome rectangular outline objects.

    Odd-width interiors become 7; even-width interiors become 2.
    """
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))

            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            border = set()
            for cc in range(c0, c1 + 1):
                border.add((r0, cc))
                border.add((r1, cc))
            for rr in range(r0, r1 + 1):
                border.add((rr, c0))
                border.add((rr, c1))
            if set(cells) != border:
                continue
            if any(grid[rr][cc] != background
                   for rr in range(r0 + 1, r1)
                   for cc in range(c0 + 1, c1)):
                continue

            fill = 7 if (c1 - c0 - 1) % 2 == 1 else 2
            for rr in range(r0 + 1, r1):
                for cc in range(c0 + 1, c1):
                    out[rr][cc] = fill

    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
